<script setup>
import { computed, onUnmounted, ref } from 'vue';
import { qlfPresets, qlfLabel, analyzeRgb } from '../engines/biofilmQlfOpticalEngine.js';
const emit=defineEmits(['save']);
const selected=ref(qlfPresets[1]); const tooth=ref(8); const surface=ref('Buccal'); const live=ref(false); const video=ref(null); const error=ref(''); const cameraMetrics=ref(null); let frame=0;
const scan=async()=>{try{const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280}},audio:false});video.value.srcObject=stream;await video.value.play();live.value=true;error.value='';frame=requestAnimationFrame(analyzeFrame)}catch(e){error.value='Camera unavailable or permission denied. Use a sample to explore the workflow.'}};
const analyzeFrame=()=>{if(!live.value)return;try{const v=video.value;if(v?.videoWidth){const c=document.createElement('canvas');c.width=48;c.height=48;const ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(v,Math.max(0,v.videoWidth/2-24),Math.max(0,v.videoHeight/2-24),48,48,0,0,48,48);const data=ctx.getImageData(0,0,48,48).data;let r=0,g=0,b=0,n=0;for(let i=0;i<data.length;i+=4){r+=data[i];g+=data[i+1];b+=data[i+2];n++}cameraMetrics.value={...analyzeRgb(r/n,g/n,b/n),name:'Live camera sample',note:'Uncalibrated center-patch RGB estimate; affected by device and illumination.'}}}catch{cameraMetrics.value=null}frame=requestAnimationFrame(analyzeFrame)};
const stop=()=>{cancelAnimationFrame(frame);video.value?.srcObject?.getTracks().forEach(t=>t.stop());live.value=false;cameraMetrics.value=null};
onUnmounted(stop);
const display=computed(()=>cameraMetrics.value||selected.value);
const save=()=>emit('save',{module:'qlf_odontogram_scans',tooth:tooth.value,surface:surface.value,sample:display.value.name,score:display.value.score,deltaF:display.value.deltaF});
const severity=computed(()=>display.value.deltaF<-12?'Lower signal in sample':display.value.score>3?'Color signal elevated in sample':'Low signal in this sample');
</script>
<template><section class="module-card glass"><div class="module-head"><div><div class="eyebrow">01 / Optical fluorescence exploration</div><h2>Biofilm & enamel scan</h2><p>Explore how red/green camera ratios and fluorescence-loss examples are visualized. Phone cameras are not calibrated clinical QLF instruments.</p></div><span class="badge">{{live?'CAMERA ACTIVE':'SIMULATOR READY'}}</span></div><div class="two-col"><div><div class="camera-box"><video ref="video" autoplay playsinline muted v-show="live"></video><div v-if="!live" class="small" style="text-align:center">◉<br>Sample preview<br><span class="footnote">Choose a preset to load a reproducible signal</span></div><div class="scan-reticle"></div></div><div class="split" style="margin-top:10px"><button class="action" @click="live?stop():scan()">{{live?'Stop camera':'Enable camera'}}</button><span v-if="error" class="error">{{error}}</span></div><h3 style="margin-top:20px">Signal preset</h3><div class="preset-list"><button v-for="item in qlfPresets" :key="item.name" class="preset" :class="{active:selected.name===item.name}" @click="selected=item;cameraMetrics=null">{{item.name}}</button></div></div><div><div class="inner"><h3>{{display.name==='Live camera sample'?'Live camera color sample':'Illustrative sample metrics'}}</h3><div class="metric-grid"><div class="metric"><span>R / G</span><b>{{display.ratio}}</b></div><div class="metric"><span>ΔF*</span><b>{{display.deltaF}}%</b></div><div class="metric"><span>Index†</span><b>{{display.score.toFixed(1)}}</b></div></div><div class="risk"><strong>{{severity}}</strong><p>{{qlfLabel(display)}} · {{display.note}}</p></div><p class="footnote">*Camera-based color estimate or preset only—not QLF. †Educational display, not a clinical plaque score.</p></div><div class="inner" style="margin-top:12px"><h3>32-tooth chart · Universal</h3><div class="tooth-grid"><button v-for="n in 32" :key="n" class="tooth" :class="{selected:tooth===n}" @click="tooth=n">{{n}}</button></div><div class="control-row"><span class="small">Surface</span><select v-model="surface" class="select" style="width:60%"><option>Buccal</option><option>Lingual</option><option>Mesial</option><option>Distal</option><option>Occlusal</option></select></div><button class="action" style="margin-top:12px" @click="save">Save tooth observation</button></div></div></div></section></template>
